package com.rehletshifaa.notification.application;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.rehletshifaa.shared.crypto.CryptoService;
import io.micrometer.core.instrument.MeterRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
public class NotificationOutboxProcessor {
    private static final Logger log=LoggerFactory.getLogger(NotificationOutboxProcessor.class);
    private static final int BATCH_SIZE=20;
    /**
     * No provider call may start this close to lease expiry. It must exceed the slowest single delivery the
     * configured client timeouts allow (SMTP connect+write+read, HTTP connect+read), or a reclaiming worker
     * could send the same message while this one is still inside its call.
     */
    public static final java.time.Duration SEND_MARGIN=java.time.Duration.ofSeconds(60);
    private final NotificationOutboxStore store; private final List<NotificationChannelPort> channels; private final ObjectMapper json; private final String webBaseUrl; private final CryptoService crypto; private final MeterRegistry metrics; private final java.time.Clock clock;
    private volatile boolean stopping;
    public NotificationOutboxProcessor(NotificationOutboxStore store,List<NotificationChannelPort> channels,ObjectMapper json,@org.springframework.beans.factory.annotation.Value("${app.web-base-url:http://localhost:3000}")String webBaseUrl,CryptoService crypto,MeterRegistry metrics,java.time.Clock clock){this.store=store;this.channels=channels;this.json=json;this.webBaseUrl=webBaseUrl;this.crypto=crypto;this.metrics=metrics;this.clock=clock;}
    /** Shutdown has begun: finish the in-flight send, hand every other claimed message straight back. */
    @org.springframework.context.event.EventListener(org.springframework.context.event.ContextClosedEvent.class) void stop(){stopping=true;}
    /**
     * Deliberately not transactional: an email or WhatsApp message cannot be rolled back, so holding a
     * database transaction across the provider call would mean a late failure re-sends everything in the
     * batch. Claiming and recording each outcome are separate short transactions inside the store.
     */
    @Scheduled(fixedDelayString="${app.notifications.poll-milliseconds:5000}")
    public void dispatch(){
        if(stopping)return;
        for(NotificationOutboxStore.OutboxMessage message:store.claim(BATCH_SIZE)){
            if(stopping||!clock.instant().isBefore(message.leaseExpiresAt().minus(SEND_MARGIN))){store.release(message.id(),message.attempts());continue;}
            deliver(message);
        }
    }
    private void deliver(NotificationOutboxStore.OutboxMessage message){
        NotificationChannelPort channel=channels.stream().filter(c->c.supports(message.channel())).findFirst().orElse(null);
        if(channel==null){fail(message,"CHANNEL_NOT_CONFIGURED",false);return;}
        Template rendered;
        try{rendered=render(message.templateKey(),message.templateData());}
        catch(Exception e){fail(message,"TEMPLATE_FAILURE",true);return;} // never retryable: the data will not improve
        String reference;
        try{reference=channel.deliver(new OutgoingNotification(message.destination(),rendered.subject(),rendered.body(),message.templateKey(),rendered.language(),rendered.parameters(),rendered.linkPath(),message.idempotencyKey()));}
        catch(UndeliverableNotificationException e){fail(message,e.code(),true);return;} // e.g. no approved template: retrying cannot help
        catch(Exception e){fail(message,"PROVIDER_FAILURE",false);return;}
        // The provider accepted it. A failure to record that must not be booked as a provider failure (which
        // would schedule a deliberate re-send); the lease is left to expire, as for a crash at this point.
        try{if(store.recordDelivered(message.id(),message.attempts(),reference))count(message,"delivered");}
        catch(RuntimeException e){count(message,"delivered_unrecorded");log.error("Notification delivered but outcome not recorded: id={} channel={} attempt={}/{}",message.id(),message.channel(),message.attempts(),message.maxAttempts());}
    }
    private void fail(NotificationOutboxStore.OutboxMessage message,String code,boolean permanent){int max=permanent?message.attempts():message.maxAttempts();if(store.recordFailure(message.id(),message.attempts(),max,code)){String outcome=message.attempts()>=max?"dead_letter":"retry";count(message,outcome);log.warn("Notification delivery {}: id={} channel={} code={} attempt={}/{}",outcome,message.id(),message.channel(),code,message.attempts(),message.maxAttempts());}}
    private void count(NotificationOutboxStore.OutboxMessage message,String outcome){metrics.counter("notification.delivery","channel",message.channel(),"outcome",outcome).increment();}
    private Template render(String key,String raw){try{String clear=com.rehletshifaa.shared.crypto.EncryptedText.decode(crypto,raw);Map<String,String> data=json.readValue(clear,new TypeReference<>(){});return switch(key){case "consultant-credential-expiry"->new Template("Credential renewal reminder","A verified credential expires within "+data.get("days")+" day(s). Sign in to your consultant workspace to submit a renewal.");case "affiliation-declaration-due"->new Template("Your affiliation declaration is due","Your yearly declaration of your relationships with the hospitals and clinics you use ends within "+data.get("days")+" day(s). Sign in to your Virtual Clinic to file this year's declaration; without a current one you cannot receive new cases.");case "facility-accreditation-expiry"->new Template("Accreditation renewal reminder","The "+data.get("body")+" accreditation of "+data.get("facility")+" expires within "+data.get("days")+" day(s). Please send RehletShifaa the renewed certificate before it lapses.");case "new-case-received"->new Template("New care request"+caseRef(data)+" — waiting in the team queue","A new care request"+caseRef(data)+" has been received and is waiting in the coordination team queue for a coordinator to take ownership. Sign in to the secure portal to review it.");case "staff-work-assigned"->new Template("Action required"+caseRef(data)+": "+data.get("title"),"You have new work in the RehletShifaa portal"+caseRef(data)+": "+data.get("title")+". Sign in to the secure portal to act on it.");case "coordinator-work-assigned"->new Template("Coordinator action"+caseRef(data)+": "+data.get("title"),caseLabel(data)+" needs you as its coordinator: "+data.get("title")+". Open your coordinator workspace in the secure portal to act on it.");case "consultant-work-assigned"->new Template("Consultant action"+caseRef(data)+": "+data.get("title"),"You have new consultant work"+caseRef(data)+": "+data.get("title")+". Open your consultant workspace in the secure portal to review the case and record your clinical decision.");case "deposit-settled-coordinator"->new Template("Deposit received"+caseRef(data)+" — case ready for coordination","The coordination deposit"+caseRef(data)+" has been settled. The case is waiting in the team queue for a coordinator to start treatment coordination.");
// Patient-facing: language, body parameters and the link path travel with the text, for template channels.
case "case-status-link"->linked(data,"status","Your RehletShifaa case was received","Your case was received. Check its status securely: %s","استلمنا حالتك في رحلة شفاء","استلمنا حالتك. تابع حالتها بأمان: %s");case "patient-action-link"->linked(data,"status","Action required for your RehletShifaa case","Your coordinator needs information from you. Respond securely: %s","مطلوب منك إجراء في حالتك لدى رحلة شفاء","يحتاج منسّقك إلى معلومات منك. أرسل ردّك بأمان: %s");case "patient-action-reminder"->linked(data,"status","Reminder: your coordinator is waiting for your reply","Your coordinator is still waiting for the information they asked for, so your case can continue. Respond securely: %s","تذكير: منسّقك بانتظار ردّك","ما زال منسّقك بانتظار المعلومات التي طلبها لمتابعة حالتك. أرسل ردّك بأمان: %s");case "information-request-closed"->text(data,"Your RehletShifaa case has been closed","We closed your case because we did not hear back about the information your coordinator asked for. If you still need care, reply to this message or send your case again, and we will pick it up from there.","أُغلقت حالتك في رحلة شفاء","أغلقنا حالتك لأننا لم نتلقَّ ردّك على المعلومات التي طلبها منسّقك. إن كنت ما زلت بحاجة إلى العلاج، فردّ على هذه الرسالة أو أرسل حالتك من جديد، وسنتابع من هناك.");case "secure-message"->linked(data,"status","New secure message from RehletShifaa","A new secure message is available. Check your case securely: %s","رسالة آمنة جديدة من رحلة شفاء","لديك رسالة آمنة جديدة. اطّلع على حالتك بأمان: %s");case "proposal-ready"->linked(data,"proposal","Your treatment proposal is ready","Your treatment proposal is ready to review securely: %s — you will confirm a one-time code before anything is shown.","مقترح علاجك جاهز","مقترح علاجك جاهز للمراجعة بأمان: %s — ستؤكّد رمزًا لمرة واحدة قبل عرض أي شيء.");case "final-quote-ready"->linked(data,"proposal","Your final quote is ready","Your final quote is ready to review securely: %s — you will confirm a one-time code before anything is shown.","عرض السعر النهائي جاهز","عرض السعر النهائي جاهز للمراجعة بأمان: %s — ستؤكّد رمزًا لمرة واحدة قبل عرض أي شيء.");case "onboarding-activation"->linked(data,"activate","Complete your RehletShifaa profile","You acknowledged your preliminary estimate. One secure link now covers everything that comes next: completing your profile, your coordination deposit, and access to your secure portal. Complete My Profile: %s — for your security you will confirm a one-time code first.","أكمل ملفك في رحلة شفاء","أقررتَ بتقديرك المبدئي. رابط آمن واحد يغطي الآن كل ما يلي: إكمال ملفك، ووديعة التنسيق، والدخول إلى بوابتك الآمنة. أكمل ملفي: %s — لحمايتك ستؤكّد رمزًا لمرة واحدة أولًا.");case "case-access-code","proposal-access-code"->code(data);case "conversation-text"->conversationText(data);case "coordinator-intro"->coordinatorIntro(data);case "out-of-hours"->text(data,"RehletShifaa","Thank you for contacting RehletShifaa. Our coordinators are available Saturday to Thursday, 10:00–20:00 Cairo time, and will reply when we open.","رحلة شفاء","شكراً لتواصلك مع رحلة شفاء. منسّقونا متاحون من السبت إلى الخميس، من 10:00 إلى 20:00 بتوقيت القاهرة، وسيردّون عليك عند بدء العمل.");case "intake-followup"->text(data,"Your RehletShifaa coordinator has an update","Your RehletShifaa coordinator has an update for you. Reply to this message to continue the conversation.","لدى منسّقك في رحلة شفاء تحديث لك","لدى منسّقك في رحلة شفاء تحديث لك. ردّ على هذه الرسالة لمتابعة المحادثة.");case "proposal-decision-recorded"->decisionRecorded(data);case "deposit-settled-patient"->text(data,"Your treatment journey is now active","We have received your coordination deposit. Your RehletShifaa coordinator is starting the next stage of your treatment journey and will contact you shortly.","بدأت رحلتك العلاجية","استلمنا وديعة التنسيق. يبدأ منسّقك في رحلة شفاء المرحلة التالية من رحلتك العلاجية وسيتواصل معك قريبًا.");case "deposit-payment-due"->portal(data,"Your coordination deposit is due","Your profile is complete. Pay your coordination deposit by bank transfer, then enter the transaction reference your bank gives you on your case page: %s","حان موعد سداد وديعة التنسيق","اكتمل ملفك. ادفع وديعة التنسيق بتحويل بنكي، ثم أدخل الرقم المرجعي للعملية الذي يعطيك إياه البنك في صفحة حالتك: %s");case "deposit-payment-reminder"->portal(data,"Reminder: your coordination deposit","We have not received the reference for your coordination deposit transfer yet. Once you have paid by bank transfer, enter the transaction reference on your case page: %s","تذكير: وديعة التنسيق","لم يصلنا بعد الرقم المرجعي لتحويل وديعة التنسيق. بعد إتمام التحويل البنكي، أدخل الرقم المرجعي للعملية في صفحة حالتك: %s");case "deposit-transfer-rejected"->portal(data,"We could not confirm your transfer","Our finance team could not confirm the transfer reference you sent. Please check the details on your case page and enter the reference again: %s","تعذّر تأكيد تحويلك","لم يتمكن فريق المالية من تأكيد الرقم المرجعي الذي أرسلته. راجِع التفاصيل في صفحة حالتك وأدخل الرقم المرجعي مرة أخرى: %s");case "deposit-balance-due"->portal(data,"Part of your deposit is still due","We received part of your coordination deposit. The remaining amount is on your case page: pay it by bank transfer and enter the new transaction reference there: %s","جزء من وديعتك ما زال مستحقًا","استلمنا جزءًا من وديعة التنسيق. المبلغ المتبقي موضّح في صفحة حالتك: ادفعه بتحويل بنكي وأدخل الرقم المرجعي الجديد للعملية هناك: %s");case "document-cleared"->portal(data,"Your file passed our virus check","A file you sent us could not be checked for viruses at the time. It has now passed the check and is on your case. See it on your case page: %s","اجتاز ملفك فحص الفيروسات","تعذّر فحص ملف أرسلته إلينا من الفيروسات في حينه. وقد اجتاز الفحص الآن وأصبح ضمن حالتك. اطّلع عليه في صفحة حالتك: %s");case "admission-balance-due"->portal(data,"Your hospital admission voucher is ready","Your hospital has your admission voucher. Pay the balance at the hospital cashier before admission: the amount and your voucher number are on your case page: %s","قسيمة دخولك إلى المستشفى جاهزة","تسلّم المستشفى قسيمة دخولك. ادفع الرصيد المتبقي في خزينة المستشفى قبل الدخول: المبلغ ورقم القسيمة في صفحة حالتك: %s");case "cleared-for-admission"->portal(data,"You are cleared for admission","Your payment is confirmed and you are cleared for admission. Your admission details are on your case page: %s","أنت جاهز للدخول إلى المستشفى","تأكّد سدادك وأصبحت جاهزًا للدخول إلى المستشفى. تفاصيل دخولك في صفحة حالتك: %s");case "treatment-update"->portal(data,"An update on your treatment","Your care team has added an update to your treatment timeline. See it on your case page: %s","تحديث عن علاجك","أضاف فريق رعايتك تحديثًا إلى سجل علاجك. اطّلع عليه في صفحة حالتك: %s");case "change-order-review"->portal(data,"A change to your treatment needs your decision","Your doctor proposes a change to your treatment that is outside your accepted quote. Review the reason and the price, then accept or decline it on your case page: %s","تغيير في علاجك يحتاج إلى قرارك","يقترح طبيبك تغييرًا في علاجك خارج عرض السعر الذي قبلته. راجِع السبب والسعر، ثم اقبله أو ارفضه في صفحة حالتك: %s");case "change-order-applied"->portal(data,"A change was made to your treatment","Your care team made a change to your treatment. The reason and, once priced, the cost are on your case page: %s","أُجري تغيير في علاجك","أجرى فريق رعايتك تغييرًا في علاجك. السبب والتكلفة بعد تسعيرها في صفحة حالتك: %s");case "discharge-pack-ready"->portal(data,"Your discharge documents are ready","You have been discharged. Your discharge documents, your medicines, the warning signs to watch for and your follow-up date are on your case page: %s","وثائق خروجك جاهزة","تمّ خروجك من المستشفى. وثائق الخروج وأدويتك وعلامات الخطر التي يجب الانتباه لها وموعد متابعتك في صفحة حالتك: %s");case "statement-ready"->portal(data,"Your statement is ready","Your statement is ready: what you were charged, what you paid and any balance or credit. See it on your case page: %s","كشف حسابك جاهز","كشف حسابك جاهز: ما احتُسب عليك وما دفعته وأي رصيد مستحق أو مبلغ مسترد. اطّلع عليه في صفحة حالتك: %s");case "follow-up-reminder"->portal(data,"Your follow-up is tomorrow","Your follow-up with your doctor is tomorrow. The time and how it will happen are on your case page: %s","موعد متابعتك غدًا","موعد متابعتك مع طبيبك غدًا. الوقت وطريقة المتابعة في صفحة حالتك: %s");case "outcome-request"->linked(data,"status","How are you since your treatment?","Your care team would like to know how you are since your treatment: four short questions about pain, daily activities, satisfaction and any problem since you went home. Answer securely: %s — you will confirm a one-time code first.","كيف حالك بعد علاجك؟","يودّ فريق رعايتك أن يعرف كيف حالك بعد العلاج: أربعة أسئلة قصيرة عن الألم والأنشطة اليومية والرضا وأي مشكلة منذ عودتك. أجب بأمان: %s — ستؤكّد رمزًا لمرة واحدة أولًا.");case "closure-review"->portal(data,"Your follow-up is complete","Your follow-up with RehletShifaa is complete and your case is closed. We would value a few words on your journey; your final statement is on your case page: %s","اكتملت متابعتك","اكتملت متابعتك مع رحلة شفاء وأُغلقت حالتك. يسعدنا أن تشاركنا كلمات قليلة عن رحلتك؛ كشف حسابك الختامي في صفحة حالتك: %s");case "admission-voucher-facility"->facilityVoucher(data);case "account-link-continue"->accountLink(data);default->throw new IllegalArgumentException("Unknown notification template");};}catch(Exception e){throw new IllegalStateException("Invalid notification template data",e);}}
    /** A patient link: the full URL in the text, and {@code <lang>/<route>/<token>} for a template's URL button. */
    private Template linked(Map<String,String> data,String route,String subject,String body,String subjectAr,String bodyAr){String token=data.get("token");if(token==null||token.isBlank())throw new IllegalArgumentException("Link token missing");boolean ar="ar".equals(lang(data));String path=lang(data)+"/"+route+"/"+token;return new Template(ar?subjectAr:subject,(ar?bodyAr:body).formatted(webBaseUrl+"/"+path),lang(data),List.of(),path);}
    /** A patient text without a link, in the patient's language (the Arabic wording awaits the native review, G-13). */
    /** A message that links to the patient's own case page (sign-in required, no token): /<lang>/portal?case=<id>. */
    private Template portal(Map<String,String> data,String subject,String body,String subjectAr,String bodyAr){String caseId=data.get("case");if(caseId==null||!caseId.matches("[0-9a-fA-F-]{36}"))throw new IllegalArgumentException("Case id missing");boolean ar="ar".equals(lang(data));String path=lang(data)+"/portal?case="+caseId;return new Template(ar?subjectAr:subject,(ar?bodyAr:body).formatted(webBaseUrl+"/"+path),lang(data),List.of(),path);}
    private Template text(Map<String,String> data,String subject,String body,String subjectAr,String bodyAr){boolean ar="ar".equals(lang(data));return new Template(ar?subjectAr:subject,ar?bodyAr:body,lang(data),List.of(),null);}
    private Template accountLink(Map<String,String> data){String url=webBaseUrl+"/"+lang(data)+"/portal?link="+data.get("token");
        return "ar".equals(lang(data))
            ?new Template("تابع بأمان مع رحلة شفاء","بدأت حالة في رحلة شفاء باستخدام عنوان البريد الإلكتروني هذا. إن كان هذا أنت، أو كنت تساعد أحد أفراد عائلتك، فسجّل الدخول للمتابعة بأمان: "+url+" — إن لم تتعرّف على ذلك، يمكنك تجاهل هذه الرسالة بأمان. ينتهي هذا الرابط الخاص لحمايتك.","ar",List.of(),null)
            :new Template("Continue securely with RehletShifaa","A RehletShifaa case was started using this email address. If this was you, or you are helping a family member, sign in to continue securely: "+url+" — if you do not recognise this, you can safely ignore this message. This private link expires for your security.","en",List.of(),null);}
    /** The case's coordinator introduced by name to someone who was talking to another coordinator before sending their case. */
    private Template coordinatorIntro(Map<String,String> data){String name=data.get("name");if(name==null||name.isBlank())throw new IllegalArgumentException("Coordinator name missing");return "ar".equals(lang(data))?new Template("منسّقك في رحلة شفاء","مرحباً، سيكون "+name+" من رحلة شفاء منسّقك من الآن وسيتابع محادثتك هنا.","ar",List.of(name),null):new Template("Your RehletShifaa coordinator","Hello, "+name+" from RehletShifaa will be your coordinator from now on and will continue your conversation here.","en",List.of(name),null);}
    /** A coordinator's reply inside WhatsApp's 24-hour window: the text itself, sent as written. */
    private Template conversationText(Map<String,String> data){String body=data.get("body");if(body==null||body.isBlank())throw new IllegalArgumentException("Reply text missing");return new Template("",body,lang(data),List.of(),null);}
    /** A one-time code; the payload names no language, so a template channel uses its configured default. */
    private static Template code(Map<String,String> data){String code=data.get("code");if(code==null||code.isBlank())throw new IllegalArgumentException("Code missing");String l=data.get("lang");String language="ar".equals(l)||"en".equals(l)?l:null;return "ar".equals(l)?new Template("رمز التحقق من رحلة شفاء","رمز التحقق الخاص بك هو "+code+". تنتهي صلاحيته خلال 15 دقيقة. لا تشاركه مع أي أحد.",language,List.of(code),null):new Template("Your RehletShifaa verification code","Your verification code is "+code+". It expires in 15 minutes. Do not share it with anyone.",language,List.of(code),null);}
    /**
     * P1-15 (D-B): the admission voucher, emailed to the hospital's contact. The facts the hospital needs to admit and bill, in
     * English then Arabic; amounts in EGP. No clinical detail.
     */
    private Template facilityVoucher(Map<String,String> data){
        String voucher=required(data,"voucher"),caseNumber=required(data,"caseNumber"),patient=required(data,"patient"),facility=required(data,"facility"),admission=required(data,"admission");
        String pkg=required(data,"package"),credit=required(data,"credit"),atFacility=required(data,"atFacility");
        String body="RehletShifaa admission voucher "+voucher+"\n\nFacility: "+facility+"\nCase: "+caseNumber+"\nPatient: "+patient+"\nPlanned admission: "+admission
                +"\n\nPackage price (EGP): "+pkg+"\nDeposit credit RehletShifaa settles to the facility (EGP): "+credit+"\nThe patient pays at your cashier before admission (EGP): "+atFacility
                +"\n\nPlease admit against this voucher and send the cashier's receipt and the admission number to your RehletShifaa operations contact."
                +"\n\nقسيمة دخول من رحلة شفاء "+voucher+"\n\nالمنشأة: "+facility+"\nالحالة: "+caseNumber+"\nالمريض: "+patient+"\nموعد الدخول المخطط: "+admission
                +"\n\nسعر الباقة (جنيه مصري): "+pkg+"\nرصيد الوديعة الذي تسدّده رحلة شفاء للمنشأة (جنيه مصري): "+credit+"\nيدفع المريض في خزينتكم قبل الدخول (جنيه مصري): "+atFacility
                +"\n\nيُرجى إدخال المريض بموجب هذه القسيمة وإرسال إيصال الخزينة ورقم الدخول إلى جهة اتصالكم في عمليات رحلة شفاء.";
        return new Template("RehletShifaa admission voucher "+voucher+" / قسيمة دخول",body,"en",List.of(),null);
    }
    private static String required(Map<String,String> data,String key){String v=data.get(key);if(v==null||v.isBlank())throw new IllegalArgumentException("Voucher field missing: "+key);return v;}
    private String lang(Map<String,String> data){String l=data.get("lang");return "ar".equals(l)?"ar":"en";}
    /** " for case RS-…" when the payload names a case, else nothing — the only case fact that travels by email. */
    private static String caseRef(Map<String,String> data){String c=data.get("case");return c==null||c.isBlank()?"":" for case "+c;}
    /** "Case RS-…" when the payload names a case, else "A case" (QA W-9: never "Case for case RS-…"). */
    private static String caseLabel(Map<String,String> data){String c=data.get("case");return c==null||c.isBlank()?"A case":"Case "+c;}
    private record Template(String subject,String body,String language,List<String> parameters,String linkPath){Template(String subject,String body){this(subject,body,null,List.of(),null);}}

    /** "8 October 2026" / "8 أكتوبر 2026" from an ISO day; the raw value if it is not one. */
    private static String readableDate(String iso,boolean ar){
        if(iso==null||iso.isBlank())return "";
        try{return java.time.LocalDate.parse(iso).format(java.time.format.DateTimeFormatter.ofPattern("d MMMM yyyy",ar?java.util.Locale.forLanguageTag("ar"):java.util.Locale.ENGLISH));}
        catch(java.time.format.DateTimeParseException e){return iso;}
    }

    /** A decision the coordinator recorded for the patient (Arabic assisted path): plain words in the patient's language. */
    private Template decisionRecorded(Map<String,String> data){
        boolean ar="ar".equals(lang(data));String decision=data.getOrDefault("decision","");String date=readableDate(data.get("date"),ar);
        boolean representative="REPRESENTATIVE".equals(data.get("confirmedBy"));
        if(ar){
            String what=switch(decision){case "ACKNOWLEDGED"->"الإقرار بالتقدير المبدئي";case "ACCEPTED"->"قبول العرض النهائي";case "REVISION_REQUESTED"->"طلب تعديلات";case "DECLINED"->"رفض المقترح";default->"قرار بشأن المقترح";};
            String with=representative?"مع ممثّلك":"معك";
            return new Template("سُجّل قرارك بشأن مقترح رحلة شفاء","سُجّل قرارك بشأن مقترح رحلة شفاء ("+what+") بعد التحدث "+with+" في "+date+". إن لم يكن هذا ما اتُّفق عليه، يُرجى التواصل مع منسّقك.","ar",List.of(what,with,date),null);
        }
        String what=switch(decision){case "ACKNOWLEDGED"->"you acknowledged the preliminary estimate";case "ACCEPTED"->"you accepted the final quote";case "REVISION_REQUESTED"->"you asked for changes";case "DECLINED"->"you declined the proposal";default->"a decision on your proposal";};
        String with=representative?"your representative":"you";
        return new Template("Your RehletShifaa proposal decision was recorded","Your coordinator recorded your decision on your RehletShifaa proposal ("+what+") after speaking with "+with+" on "+date+". If this is not what was agreed, please contact your coordinator.","en",List.of(what,with,date),null);
    }
}
